<script setup>
import { computed, ref, onMounted, watch } from 'vue'
import { RouterLink } from 'vue-router'
import { sectionEditorials } from '../../data/sectionEditorials'
import { pages } from '../../data/pages'
const props = defineProps({ pageKey: String })
const content = computed(() => sectionEditorials[props.pageKey])
const nextPages = computed(() => content.value?.next.map(key => pages.find(page => page.key === key)) || [])
const checklist = ['已核对官方预约与开放公告', '已确认到达与返程交通', '已准备证件与预约凭证', '已备好饮水、防晒与舒适鞋履', '已查看天气并预留行程弹性']
const checked = ref([])
const storageIssue = ref(false)
onMounted(() => {
  try { const data = JSON.parse(localStorage.getItem('dunhuang-travel-checklist') || '[]'); if (Array.isArray(data)) checked.value = data.filter(value => Number.isInteger(value) && value >= 0 && value < checklist.length) }
  catch { storageIssue.value = true }
})
watch(checked, value => { try { localStorage.setItem('dunhuang-travel-checklist', JSON.stringify(value)); storageIssue.value = false } catch { storageIssue.value = true } }, { deep:true })
</script>

<template>
 <div v-if="content" class="section-afterword">
  <section v-if="pageKey === 'guide'" class="travel-checklist"><div><p>READY TO GO</p><h3>出发前的小清单</h3><span>勾选一项，准备就更近一步。</span><strong>{{ checked.length }}<small> / {{ checklist.length }}</small></strong><div class="check-progress"><i :style="{ width: `${checked.length / checklist.length * 100}%` }"></i></div><small>{{ storageIssue ? '当前浏览器无法保存，勾选仅本次有效。' : '勾选记录保存在当前浏览器。' }}</small></div><fieldset><legend class="sr-only">出行准备清单</legend><label v-for="(item,i) in checklist" :key="item" :class="{ checked: checked.includes(i) }"><input v-model="checked" type="checkbox" :value="i"><span>{{ item }}</span><small>0{{ i + 1 }}</small></label></fieldset></section>
  <section class="afterword-notes"><div class="afterword-heading"><p>GOOD TO KNOW / 再了解一点</p><h3>带着问题，继续探索。</h3></div><div class="afterword-questions"><details v-for="(tip,i) in content.tips" :key="tip[0]"><summary><span>0{{ i + 1 }}</span>{{ tip[0] }}<i aria-hidden="true">+</i></summary><p>{{ tip[1] }}</p></details></div></section>
  <section class="continue-exploring"><div class="afterword-heading"><p>THE JOURNEY CONTINUES</p><h3>下一站，去哪里？</h3></div><div class="continue-grid"><RouterLink v-for="(page,i) in nextPages" :key="page.key" :to="page.route"><img :src="'/images/' + page.image" :alt="page.title + '主题配图'" loading="lazy"><div><small>0{{ i + 1 }} / {{ page.key.toUpperCase() }}</small><h4>{{ page.title }}<span>↗</span></h4><p>{{ page.subtitle }}</p></div></RouterLink></div></section>
 </div>
</template>

<style scoped>
