3px,-3px)}.continue-grid p{font-size:10px;color:#dbcdb5}.travel-checklist{display:grid;grid-template-columns:1fr 1.4fr;gap:55px;background:#eae2d2;border:1px solid #d9ccb4;padding:35px;margin-bottom:45px}.travel-checklist>div>span{font-size:11px;color:#9a8564;display:block;margin-top:10px}.travel-checklist strong{font:48px Georgia,serif;display:block;color:#997442;margin-top:20px}.travel-checklist strong small{font-size:16px;color:#b29c79}.check-progress{height:2px;background:#d6c6a8;margin:14px 0 8px}.check-progress i{display:block;height:100%;background:#8a734b;transition:width .4s}.travel-checklist>div>small{font-size:9px;color:#a38e6a}.travel-checklist fieldset{border:0;min-width:0;padding:0;margin:0;display:grid;align-content:center}.travel-checklist label{display:flex;align-items:center;gap:13px;border-bottom:1px solid #d9cbb2;padding:17px 0;font-size:12px;color:#8e7b5c;cursor:pointer}.travel-checklist input{accent-color:#887247;width:16px;height:16px}.travel-checklist label small{font:11px Georgia,serif;color:#b29a73;margin-left:auto}.travel-checklist label.checked>span{color:#777e58}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@keyframes afterword-in{from{opacity:.6;transform:translateY(-6px)}to{opacity:1;transform:none}}@media(max-width:800px){.afterword-notes{gap:25px;grid-template-columns:1fr 1.7fr}.continue-grid{gap:12px}.continue-grid>a>div{padding:20px}.continue-grid h4{font-size:22px}.travel-checklist{padding:28px;gap:25px}}@media(max-width:550px){.afterword-notes{grid-template-columns:1fr;gap:18px;padding:30px 0}.afterword-heading h3{font-size:25px}.continue-grid{grid-template-columns:1fr}.continue-grid>a{min-height:180px}.travel-checklist{grid-template-columns:1fr;padding:24px;gap:15px}.travel-checklist strong{font-size:38px}.section-afterword{margin-top:45px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
